CREATE DATABASE customer_behavior;

use customer_behavior;

select * from customer limit 10;

select gender from customer limit 10;

-- Q1. What is the total revenue generated by male vs. female customers?
-- Bussinesess wants to see this revenue splits so that they can go with the specific campaigns accordingly.

select gender, count(gender) as total_num
from customer
group by gender;

select gender,count(gender) as total_num, sum(purchase_amount) as revenue
from customer
group by gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount? 

select discount_applied, purchase_amount
from customer;

select avg(purchase_amount) from customer;

select customer_id, purchase_amount
from customer
where discount_applied = 'Yes' and purchase_amount >= (select avg(purchase_amount) from customer);

select purchase_amount from(
select customer_id, purchase_amount
from customer
where discount_applied = 'Yes' and purchase_amount >= (select avg(purchase_amount) from customer)) as sub_table
where purchase_amount < 56.7;

-- Q3. Which are the top 5 products with the highest average review rating?

select item_purchased, round(avg(review_rating),2) as 'Avg Product Review'
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

select item_purchased, round(avg(review_rating),2) as 'Avg_Product_Review'
from customer
group by item_purchased
order by Avg_Product_Review desc
limit 5;

-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 

select shipping_type, round(avg(purchase_amount),2) as 'Avg Pur_Amt on Shipping_type'
from customer
where shipping_type = 'Express' or shipping_type = 'Standard'
group by shipping_type;

select shipping_type, round(avg(purchase_amount),2) as 'Avg Pur_Amt on Shipping_type'
from customer
where shipping_type in ('Express','Standard')
group by shipping_type;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

select count(customer_id) as 'Total_Customer', subscription_status, avg(purchase_amount) as 'Avg_Pur_Amt', sum(purchase_amount) as'Total_Revenue'
from customer
group by subscription_status;

SELECT subscription_status,
       COUNT(customer_id) AS total_customers,
       ROUND(AVG(purchase_amount),2) AS avg_spend,
       ROUND(SUM(purchase_amount),2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue,avg_spend DESC;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
-- "Exactly 50% of all hats sold in our dataset were purchased using a discount code."
select item_purchased,
round(100 * sum(case when discount_applied = 'yes' then 1 else 0 end)/count(*),2) as discount_rating
from customer
group by item_purchased
order by discount_rating desc
limit 5;

-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.

with customer_type as (
select customer_id, previous_purchases,
case 
	when previous_purchases = 1 then 'New'
    when previous_purchases between 2 and 10 then 'Returning'
    else 'Loyal'
    end as customer_segment
from customer)

select customer_segment,count(*) as 'Number of customers'
from customer_type
group by customer_segment;

select * from customer_type;

-- Q8. What are the top 3 most purchased products within each category? 
select item_purchased, round(avg(review_rating),2) as Avg_Product_Rating
from customer
where category = 'Clothing'
group by item_purchased
order by avg(review_rating) desc
limit 3;

select item_purchased, round(avg(review_rating),2) as Avg_Product_Rating
from customer
where category = 'Accessories'
group by item_purchased
order by avg(review_rating) desc
limit 3;

select item_purchased, round(avg(review_rating),2) as Avg_Product_Rating
from customer
where category = 'Footwear'
group by item_purchased
order by avg(review_rating) desc
limit 3;

select item_purchased, round(avg(review_rating),2) as Avg_Product_Rating
from customer
where category = 'Outerwear'
group by item_purchased
order by avg(review_rating) desc
limit 3;

select item_purchased, count(customer_id) as Total_Customers
from customer
where category = 'Outerwear'
group by item_purchased
order by Total_Customers desc;

with items_counts as (
	select category, item_purchased, count(customer_id) as total_orders,
	row_number() over(partition by category order by count(customer_id) desc) as items_rank
from customer
group by category,item_purchased
)
select items_rank, category, item_purchased, total_orders
from items_counts
where items_rank <=3;

-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

select customer_id, subscription_status, previous_purchases
from customer
where subscription_status = 'Yes' and previous_purchases > 5;

with count_cus as (
	select customer_id, subscription_status, previous_purchases
    from customer
	where subscription_status = 'Yes' and previous_purchases > 5
)
select subscription_status, count(customer_id) as total_customers
from count_cus;


SELECT subscription_status,
       COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

-- Q10. What is the revenue contribution of each age group? 

select age_group, sum(purchase_amount) as revenue
from customer
group by age_group
order by revenue desc;